:param[$N$]{}

:param[$f$]{}

:param[$w$]{}

:var[$y$]{}

$$
y = \sum_{1 \le i \le N - 1}^{\{f\}} w_{i}
$$

---
esm: "2.4.0"
name: "fixture"
---

::model[M]

:param[$N$]{}

:param[$f$]{}

:param[$g$]{}

:var[$y$]{}

$$
y = \left(\left[\sum\left(f_{i + 1} - f_{i}\right)\right]^{\{f, g\}}_{2 \le i \le N - 1}\right)^{2}
$$

---
esm: "2.4.0"
name: "fixture"
---

::model[M]

:param[$N$]{}

:param[$a$]{}

:param[$x$]{}

:var[$y$]{}

$$
y = \left[\begin{array}{l|l} \operatorname{interior}(u = x) & [2, N - 1] \\ 2 a & [1, 1] \\ 0 & [N, N] \end{array}\right]
$$

